const grid=document.querySelector('#proposal-grid');
const dialog=document.querySelector('#proposal-dialog');
let previousFocus;
function proposalCard(p){
 return `<article class="proposal"><div class="proposal-top"><span>Política propuesta</span><span>${p.id} / 10</span></div><strong class="stat">${p.stat}</strong><p class="stat-label">${p.label}</p><h4>${p.title}</h4><button data-id="${p.id}" aria-label="Ver propuesta: ${p.title}">Conocé la propuesta <span aria-hidden="true">↗</span></button></article>`;
}
function render(filter='Todos'){
 const visibleAxes=axes.filter(a=>filter==='Todos'||a.topic===filter);
 const list=proposals.filter(p=>filter==='Todos'||p.topic===filter);
 grid.innerHTML=visibleAxes.map(a=>{
 const policies=proposals.filter(p=>p.topic===a.topic);
 return `<section class="axis-block" aria-labelledby="axis-${a.id}" id="eje-${a.id}">
 <div class="axis-topline"><span>EJE ${a.number} / ${a.name.toUpperCase()}</span><span>${policies.length} POLÍTICA${policies.length===1?'':'S'}</span></div>
 <div class="axis-lead"><h3 id="axis-${a.id}">${a.title}</h3><p class="axis-question">${a.question}</p></div>
 <div class="axis-diagnosis"><div class="axis-story"><span class="axis-label">EL PROBLEMA QUE QUEREMOS TRANSFORMAR</span>${a.paragraphs.map(p=>`<p>${p}</p>`).join('')}</div>
 <aside class="axis-evidence" aria-label="Datos del eje">${a.evidence.map(d=>`<div><strong>${d.value}</strong><p>${d.text}</p><small>${d.period}</small></div>`).join('')}</aside></div>
 <details class="axis-depth"><summary>Profundizar: factores, actores y horizonte <span aria-hidden="true">+</span></summary><div class="axis-depth-grid"><div><h4>FACTORES A ABORDAR</h4><ul>${a.factors.map(f=>`<li>${f}</li>`).join('')}</ul></div><div><h4>ACTORES A ARTICULAR</h4><p>${a.actors}</p><h4>HACIA DÓNDE QUEREMOS IR</h4><p>${a.direction}</p></div></div></details>
 <p class="axis-reference">${a.source}${a.readMore?` <a href="${a.readMore.url}" target="_blank" rel="noopener">${a.readMore.label} ↗</a>`:''}</p>
 <div class="axis-policies-heading"><span>LAS POLÍTICAS DE ESTE EJE</span><span>DEL DIAGNÓSTICO A LA ACCIÓN ↓</span></div><div class="proposal-grid">${policies.map(proposalCard).join('')}</div>
 </section>`;
 }).join('');
 document.querySelector('#results').textContent=`${visibleAxes.length} eje${visibleAxes.length!==1?'s':''} · ${list.length} propuesta${list.length!==1?'s':''} para explorar`;
}
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{
 document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn));});render(btn.dataset.filter);
}));
grid.addEventListener('click',event=>{
 const button=event.target.closest('[data-id]');if(!button)return;
 const p=proposals.find(item=>item.id===button.dataset.id);previousFocus=button;
 document.querySelector('#dialog-body').innerHTML=`<div class="section-label">PROPUESTA ${p.id} / 10 · ${p.category.toUpperCase()}</div><h2 id="dialog-title">${p.title}</h2><div class="dialog-stat"><strong>${p.stat}</strong><p>${p.label}</p></div><h3>EL PUNTO DE PARTIDA</h3><p>${p.problem}</p><h3>QUÉ PROPONEMOS</h3><ul>${p.actions.map(a=>`<li>${a}</li>`).join('')}</ul><p class="reference"><b>Referencia del documento:</b> ${p.source}${p.note?`<br><br>${p.note}`:''}<br><br><a href="https://canva.link/tnjabljx8lvlqqx" target="_blank" rel="noopener">Consultar presentación original ↗</a></p>`;
 dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');
});
function closeDialog(){dialog.close();}
document.querySelector('.close').addEventListener('click',closeDialog);
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');previousFocus?.focus();});
render();
